window.MOTIF_CATALOG_CHUNKS[36]={"cards":[{"id":"MEJE-KW-003698","row_version":2,"title":"보스전을 예고하는 경보","original":"Boss Warning Siren","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"큰 적과 맞서기 직전 화면과 소리가 경고 신호로 바뀐다. 전투가 시작되기 전에 준비할 시간과 긴장을 준다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003698/index.html"},{"id":"MEJE-KW-003699","row_version":1,"title":"식물의 모습을 한 기이한 존재","original":"Botanical Abomination","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"뿌리와 줄기, 꽃이 익숙한 생명체의 범위를 벗어난 모습으로 자라난다. 식물이라는 친숙함과 알 수 없는 행동이 동시에 공포를 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-003699/index.html"},{"id":"MEJE-KW-003700","row_version":1,"title":"규칙을 지나치게 엄격히 지켜 조직 곤란하게 하기","original":"Bothering by the Book","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 문구 하나도 어기지 않고 규정을 적용해 권력자의 일을 어렵게 만든다. 규칙을 만든 쪽이 그 결과를 감당하는 역전이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003700/index.html"},{"id":"MEJE-KW-003701","row_version":1,"title":"질서와 혼란 모두 위험한 세계","original":"Both Order and Chaos are Dangerous","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"지나친 통제와 무제한의 무질서가 각각 공동체를 해친다. 어느 한쪽을 고르는 대신 무엇이 사람을 살리는 질서인지 묻게 된다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-003701/index.html"},{"id":"MEJE-KW-003702","row_version":1,"title":"양쪽 말에 일리가 있다고 중재하기","original":"\"Both Sides Have a Point\" Remark","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"대립하는 사람들의 주장 안에서 각각 맞는 부분을 찾아 말한다. 두 입장을 인정하는 말이 실제 결정을 대신할 수는 없다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003702/index.html"},{"id":"MEJE-KW-003703","row_version":1,"title":"상품을 사면 멋진 사람이 된다는 광고","original":"Bottled Cool","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"광고가 물건의 기능보다 그것을 가진 사람의 인기와 자신감을 판다. 제품과 자기 이미지 사이의 연결이 설득의 핵심이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003703/index.html"},{"id":"MEJE-KW-003704","row_version":1,"title":"위험한 약으로 잠시 힘을 되찾기","original":"Bottled Heroic Resolve","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 몸의 한계를 넘기 위해 작품 속 약을 쓰고 잠깐 다시 움직인다. 효과 뒤에 남는 대가가 선택의 무게를 만든다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003704/index.html"},{"id":"MEJE-KW-003705","row_version":2,"title":"한 공간과 소수 인물로 꾸린 회차","original":"Bottle Episode","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"드라마 한 회가 익숙한 장소와 적은 인물에 머물며 이야기를 진행한다. 제작상의 제약이 대화와 관계를 깊게 보여 주는 형식이 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003705/index.html"},{"id":"MEJE-KW-003706","row_version":2,"title":"화장실에 갈 필요가 없는 주인공","original":"Bottomless Bladder","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"긴 여정과 전투를 겪는 인물이 기본적인 생리적 필요를 거의 드러내지 않는다. 이야기의 속도를 위해 일상적 몸의 시간을 생략한 규칙이다. 몸의 필요를 생략한다는 점에서 줄지 않는 연료통의 자원 생략과 닮았다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003706/index.html"},{"id":"MEJE-KW-003707","row_version":2,"title":"줄지 않는 연료통","original":"Bottomless Fuel Tanks","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"차량이나 기계가 오래 움직여도 연료를 채울 필요가 없다. 자원 관리보다 이동과 탐험에 집중하게 하는 게임의 생략이다. 이동 자원을 줄이지 않는 규칙은 전투의 끝없이 발사되는 탄약과 함께 게임의 흐름을 빠르게 만든다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003707/index.html"},{"id":"MEJE-KW-003708","row_version":1,"title":"끝없이 발사되는 탄약","original":"Bottomless Magazines","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"무기가 재장전 없이 계속 작동하는 것처럼 보인다. 화면의 액션 리듬이 사용 가능한 탄약의 수보다 앞선다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003708/index.html"},{"id":"MEJE-KW-003709","row_version":2,"title":"추락한 플레이어를 자동으로 건져 주기","original":"Bottomless Pit Rescue Service","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"깊은 구덩이에 빠진 순간 조력자나 장치가 인물을 다시 안전한 곳으로 올린다. 실패는 남기되 진행을 끊지 않는 구제 규칙이다. 바닥이 보이지 않는 낙하 구덩이에 빠졌을 때 실패 대신 복귀를 주는 구제 장치다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003709/index.html"},{"id":"MEJE-KW-003710","row_version":1,"title":"바닥이 보이지 않는 낙하 구덩이","original":"Bottomless Pits","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 공간에 끝이 보이지 않는 구덩이를 두어 이동의 정확성을 시험한다. 떨어졌을 때의 결과가 위험 구역의 경계를 정한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003710/index.html"},{"id":"MEJE-KW-003711","row_version":1,"title":"소재가 떨어져 자극적인 농담에 기대기","original":"Bottom of the Barrel Joke","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"반복해서 새 이야기를 내야 하는 창작물이 손쉬운 외설이나 충격의 농담을 끌어온다. 웃음이 어떤 인물과 문제를 희생하는지도 살필 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003711/index.html"},{"id":"MEJE-KW-003712","row_version":1,"title":"큰 바위를 둔기로 쓰기","original":"Boulder Bludgeon","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 주변의 무거운 바위를 들어 위협하거나 공격한다. 즉석의 사물이 힘의 과장된 표지가 되는 장면이다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003712/index.html"},{"id":"MEJE-KW-003713","row_version":1,"title":"출입을 통제하는 문지기","original":"Bouncer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"행사장이나 가게의 문 앞에서 누가 들어올 수 있는지 판단하고 질서를 지킨다. 단순한 몸집보다 무엇을 기준으로 사람을 가르는지가 역할을 보여 준다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003713/index.html"},{"id":"MEJE-KW-003714","row_version":2,"title":"몸을 튕기며 싸우는 인물","original":"Bouncing Battler","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 벽과 바닥을 튕겨 이동한 힘으로 상대에게 맞선다. 무기보다 반동과 경로를 읽는 방식이 전투를 만든다. 몸을 튕기는 인물이 밟고 튀어 오를 수 있는 거품를 만나면 이동할 표면이 늘어난다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003714/index.html"},{"id":"MEJE-KW-003715","row_version":1,"title":"밟고 튀어 오를 수 있는 거품","original":"Bouncy Bubbles","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"작품 속 거품이 쉽게 터지지 않고 몸을 받아 다시 밀어 올린다. 현실과 다른 탄성 규칙이 이동과 놀이의 공간이 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003715/index.html"},{"id":"MEJE-KW-003716","row_version":1,"title":"묶이고 입이 막힌 포로","original":"Bound and Gagged","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"잡힌 인물이 몸을 움직이거나 도움을 청하기 어렵게 제압된다. 탈출의 긴장은 포로의 처지와 구하러 오는 이의 선택에서 생긴다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003716/index.html"},{"id":"MEJE-KW-003717","row_version":2,"title":"암초로 자연스럽게 막아 둔 지도 경계","original":"Boundareefs","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 끝으로 가는 길에 지나갈 수 없는 암초를 놓는다. 보이지 않는 벽 대신 지형이 탐험의 한계를 설명한다. 지형이 이동을 막는 규칙이라는 점에서 특정 지역을 벗어날 수 없는 존재의 보이지 않는 한계와 비교할 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003717/index.html"},{"id":"MEJE-KW-003718","row_version":1,"title":"특정 지역을 벗어날 수 없는 존재","original":"Bound to an Area","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"저주나 약속 때문에 한 인물은 정해진 영역 안에서만 움직인다. 경계가 보이지 않아도 넘어가려는 시도가 규칙의 힘을 드러낸다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003718/index.html"},{"id":"MEJE-KW-003719","row_version":1,"title":"보상을 받고 수배자를 쫓는 인물","original":"Bounty Hunter","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 정해진 보상을 얻기 위해 수배 대상을 찾아간다. 돈을 받는 의뢰와 개인의 판단이 충돌할 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003719/index.html"},{"id":"MEJE-KW-003720","row_version":1,"title":"결혼식에서 꽃다발 던지기","original":"Bouquet Toss","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"신부가 꽃다발을 던지고 하객이 이를 받으며 다음 결혼을 점치는 놀이를 한다. 축하의 관습이 어떤 사람에게는 기대나 압박이 될 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003720/index.html"},{"id":"MEJE-KW-003721","row_version":1,"title":"부유함과 자유로운 취향을 함께 과시하기","original":"Bourgeois Bohemian","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"인물이 높은 경제적 지위를 누리면서도 반문화적 취향과 창의성을 자기 이미지로 삼는다. 생활의 선택과 소비의 표지가 어떻게 어울리는지 본다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003721/index.html"},{"id":"MEJE-KW-003722","row_version":2,"title":"활과 검을 함께 쓰는 전투가","original":"Bow and Sword in Accord","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 먼 거리에서는 활을, 가까운 거리에서는 검을 쓴다. 두 무기 사이를 바꾸는 순간이 전투의 선택을 넓힌다. 같은 활 사용자라도 활과 쇠뇌를 성격의 대립으로 쓰기의 구도에서는 무기의 이미지가 서로 대립한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003722/index.html"},{"id":"MEJE-KW-003723","row_version":1,"title":"음란한 분위기를 흉내 내는 짧은 음악 소리","original":"Bow Chicka Wow Wow","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"인물이 상황을 성적으로 놀리려고 익숙한 악기 소리를 입으로 흉내 낸다. 음악을 직접 틀지 않아도 농담의 뜻이 전달된다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-003723/index.html"},{"id":"MEJE-KW-003724","row_version":1,"title":"기존 작품의 거친 부분을 순화해 다시 내기","original":"Bowdlerise","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"이미 만든 작품에서 욕설이나 폭력, 성적 표현을 덜어 새 판본으로 공개한다. 바뀐 기준이 이야기의 의미까지 바꾸는지 살필 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003724/index.html"},{"id":"MEJE-KW-003725","row_version":1,"title":"깜짝 놀란 배설을 벽돌 이미지로 표현하기","original":"Bowel-Breaking Bricks","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"극도의 놀람을 실제 장면 대신 우스운 벽돌 그림으로 대신한다. 관객이 알아듣는 관용적 이미지를 시각 농담으로 옮긴다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003725/index.html"},{"id":"MEJE-KW-003726","row_version":1,"title":"구르는 큰 물체가 사람들을 볼링핀처럼 쓰러뜨리기","original":"Bowled Over","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"큰 공이나 둥근 물체가 무리 사이를 지나가며 연달아 넘어뜨린다. 사람의 배열을 놀이의 핀처럼 보이게 하는 화면의 과장이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003726/index.html"},{"id":"MEJE-KW-003727","row_version":2,"title":"볼링으로 노동자 인물의 일상 표현하기","original":"Bowling for Ratings","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 평범한 노동자의 취미를 보여 주겠다며 볼링 장면을 반복한다. 취미 하나로 계층의 삶을 대표할 수 있는지도 돌아볼 필요가 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003727/index.html"},{"id":"MEJE-KW-003728","row_version":1,"title":"활쏘기 동작을 잘못 그린 장면","original":"Bows and Errors","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품 속 궁수가 몸의 움직임과 무기의 작동을 어색하게 보여 준다. 극적 구도와 설정 속 숙련도가 서로 맞는지 검토할 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003728/index.html"},{"id":"MEJE-KW-003729","row_version":1,"title":"리본으로 귀여움을 표시하기","original":"Bows for Cuteness","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"머리나 옷에 큰 리본을 달아 어린 인물이나 사랑스러운 인상을 빠르게 만든다. 장식의 뜻이 인물의 실제 성격을 모두 정하지는 않는다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003729/index.html"},{"id":"MEJE-KW-003730","row_version":1,"title":"활과 쇠뇌를 성격의 대립으로 쓰기","original":"Bows Versus Crossbows","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"같은 원거리 무기인데도 활은 품위 있게, 쇠뇌는 거칠게 보이도록 배치한다. 무기의 기능보다 사용자에게 부여한 이미지가 대비를 만든다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003730/index.html"},{"id":"MEJE-KW-003731","row_version":1,"title":"상자와 받침대로 만든 간단한 덫","original":"Box-and-Stick Trap","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"작품이 상자를 받쳐 둔 덫으로 작은 동물을 잡으려는 장면을 만든다. 실제 효율보다 누구나 알아볼 수 있는 사냥의 그림 기호다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003731/index.html"},{"id":"MEJE-KW-003732","row_version":1,"title":"위험한 임무를 조건으로 죄수 풀어 주기","original":"Boxed Crook","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"갇힌 사람에게 어려운 일을 맡기고 성공하면 자유를 주겠다고 한다. 선택의 여지가 좁은 거래와 임무의 대가가 이야기의 갈등이다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003732/index.html"},{"id":"MEJE-KW-003733","row_version":1,"title":"여러 편을 한 상자로 묶은 상품","original":"Boxed Set","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"시즌이나 연작의 여러 권·영상·음반을 하나의 꾸러미로 다시 판다. 순서대로 경험하도록 묶는 일이 작품의 유통 방식을 바꾼다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003733/index.html"},{"id":"MEJE-KW-003734","row_version":1,"title":"권투 기술로 싸우는 인물","original":"Boxing Battler","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"경기장 밖에서도 주먹과 발놀림을 전투 방식으로 쓰는 인물. 숙련된 움직임이 그 사람의 강점과 한계를 함께 보여 준다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003734/index.html"},{"id":"MEJE-KW-003735","row_version":1,"title":"권투하는 캥거루를 구경거리로 삼기","original":"Boxing Kangaroo","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"캥거루가 사람이나 다른 상대와 권투하는 것처럼 그려 흥미를 끈다. 동물의 몸짓을 스포츠로 읽는 연출과 동물에게 가해지는 부담을 구분한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003735/index.html"},{"id":"MEJE-KW-003736","row_version":2,"title":"괴롭힘을 겪는 인물에게 권투 가르치기","original":"Boxing Lesson","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 괴롭힘에 대응할 자신감을 얻으려 권투를 배운다. 실제 대립을 어떻게 해결하는지가 훈련의 의미를 정한다. 훈련을 거친 뒤 권투 기술로 싸우는 인물의 기술을 실제 갈등에 어떻게 쓸지 선택한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003736/index.html"},{"id":"MEJE-KW-003737","row_version":2,"title":"강한 초인에게 평범한 기술 더 가르치기","original":"Boxing Lessons for Superman","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"원래 큰 힘을 가진 인물이 기본적인 훈련이나 기술을 익혀 능력을 더 잘 쓴다. 힘의 크기와 그것을 다루는 솜씨는 다른 성장 축이다. 초인의 힘에 권투 기술로 싸우는 인물의 기본 동작을 더하는 전개일 수 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003737/index.html"},{"id":"MEJE-KW-003738","row_version":1,"title":"흥행 수입이 제작비에 못 미친 영화","original":"Box-Office Bomb","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"영화가 들인 비용만큼의 관객 수입을 얻지 못해 사업적으로 실패한다. 작품의 완성도에 대한 평가와 재정적 결과는 별도로 읽을 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003738/index.html"},{"id":"MEJE-KW-003739","row_version":1,"title":"남성 보컬 그룹의 대중음악 형식","original":"Boy Band","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"여러 남성 가수가 목소리와 안무, 각자의 이미지를 조합해 활동하는 음악 그룹 형식. 특정 국가나 시대의 아이돌 방식으로만 한정되지 않는다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-003739/index.html"},{"id":"MEJE-KW-003740","row_version":1,"title":"딸의 연애를 통제하려는 아버지","original":"Boyfriend-Blocking Dad","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"아버지가 자녀의 연애 상대를 위협하거나 쫓아내려 한다. 보호라는 명분과 자녀 자신의 선택권이 충돌한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003740/index.html"},{"id":"MEJE-KW-003741","row_version":1,"title":"연인인 척하며 낯선 사람의 괴롭힘 막기","original":"Boyfriend Bluff","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"한 인물이 다른 사람을 따라붙는 이에게 자신이 연인이라고 말해 상황을 벗어나게 한다. 도움의 결과와 당사자의 동의, 이후 관계를 함께 본다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003741/index.html"},{"id":"MEJE-KW-003742","row_version":1,"title":"짧은 머리로 소년 같은 인상 만들기","original":"Boyish Short Hair","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"여성 인물의 머리를 짧게 그려 중성적이거나 활동적인 인상을 만든다. 머리 길이로 성격과 성별 표현을 단정하지 않는다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003742/index.html"},{"id":"MEJE-KW-003743","row_version":1,"title":"짧은 바지로 어린 남자아이 표시하기","original":"Boyish Shorts","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"어린 남성 인물에게 반바지를 반복해서 입혀 성인과 구별한다. 옷의 길이가 나이를 알리는 그림의 약속이 된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003743/index.html"},{"id":"MEJE-KW-003744","row_version":1,"title":"살아 있는 사람과 언데드의 연애","original":"Boy Meets Ghoul","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"살아 있는 인물이 죽음 이후에도 활동하는 존재와 사랑의 관계를 맺는다. 두 사람의 욕망과 위험, 함께 지낼 규칙이 사랑 이야기의 일부다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003744/index.html"},{"id":"MEJE-KW-003745","row_version":1,"title":"두 사람이 만나고 헤어졌다 다시 만나는 연애 구조","original":"Boy Meets Girl","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"연애 이야기에서 만남과 이별, 재회의 단계를 중심 줄기로 삼는다. 과정에서 무엇을 배우고 다시 선택하는지가 결말의 의미를 만든다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003745/index.html"},{"id":"MEJE-KW-003746","row_version":1,"title":"낯선 작은 생물을 좋아하는 소년","original":"Boys Like Creepy Critters","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 어린 남자아이가 벌레나 파충류에 열광하는 모습을 익숙한 성별 특징처럼 보여 준다. 취향은 성별보다 인물의 경험에서 찾을 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003746/index.html"},{"id":"MEJE-KW-003747","row_version":2,"title":"교정기를 매력적인 모습으로 보기","original":"Braces Are Beautiful","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"치아 교정기를 한 인물의 미소를 있는 그대로 예쁘다고 그린다. 치료 도구를 부끄러움의 이유로만 보던 시선을 바꾼다. 교정기의 모습을 긍정하는 장면은 치아 교정기로 괴롭히기에 맞서는 관계가 된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003747/index.html"},{"id":"MEJE-KW-003748","row_version":2,"title":"치아 교정기로 괴롭히기","original":"Braces-Based Bullying","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가해자가 교정기를 낀 사람의 외모와 말을 놀림감으로 삼는다. 치료 중인 몸을 조롱하는 행동의 책임은 가해자에게 있다. 지나치게 거대한 치아 교정 장치의 과장된 장치가 놀림을 만드는 장면이라면 그 책임은 장치가 아니라 가해자에게 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003748/index.html"},{"id":"MEJE-KW-003749","row_version":2,"title":"지나치게 거대한 치아 교정 장치","original":"Braces of Orthodontic Overkill","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"평범한 교정기보다 훨씬 크고 복잡한 장치를 얼굴에 달아 눈에 띄게 만든다. 치료의 현실성보다 당황과 시각적 소동을 강조한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003749/index.html"},{"id":"MEJE-KW-003750","row_version":1,"title":"자기 능력을 떠벌리는 보스","original":"Braggart Boss","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"보스가 싸움 전후에 자신의 힘과 위업을 길게 자랑한다. 말과 실제 전투가 다르면 위협보다 허세의 인상이 남는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003750/index.html"},{"id":"MEJE-KW-003751","row_version":2,"title":"성과보다 과시를 위한 게임 선택지","original":"Bragging Rights Option","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"플레이어가 더 어렵거나 화려한 방식을 골라 실력과 취향을 드러낸다. 보상보다 선택을 해냈다는 경험이 목적이 된다. 과시를 위해 고른 선택의 끝에 쓸 시기가 지나서 얻는 강력한 보상가 놓일 수도 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003751/index.html"},{"id":"MEJE-KW-003752","row_version":1,"title":"쓸 시기가 지나서 얻는 강력한 보상","original":"Bragging Rights Reward","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"어려운 조건을 모두 달성한 뒤 큰 능력의 물건을 받지만 쓸 사건은 거의 남지 않는다. 실용성보다 완수의 기념이 되는 보상이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003752/index.html"},{"id":"MEJE-KW-003753","row_version":1,"title":"주인공의 능력을 자랑하는 주제가","original":"Bragging Theme Tune","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"작품의 여는 노래가 인물의 힘과 업적을 크게 부른다. 음악이 인물을 만나기 전부터 기대와 인상을 만든다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-003753/index.html"},{"id":"MEJE-KW-003754","row_version":2,"title":"원주민을 한 가지 복장으로 그리는 관습","original":"Braids, Beads and Buckskins","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"서로 다른 원주민 집단을 땋은 머리와 깃털, 가죽옷의 한 벌처럼 묘사한다. 실제 문화의 차이와 현대의 삶을 지우는 고정관념이다. 땋은 머리를 한 가지 문화의 표지로 쓰는 관습은 땋은 머리로 야성적 전사 표현하기의 전사 이미지와도 겹친다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003754/index.html"},{"id":"MEJE-KW-003755","row_version":2,"title":"땋은 머리로 활동성을 보이기","original":"Braids of Action","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"전투에 나서는 인물이 머리를 땋아 움직임을 정돈하고 시각적 인상을 만든다. 머리 모양만으로 전투 능력이 정해지지는 않는다. 같은 땋은 머리라도 땋은 머리로 야성적 전사 표현하기에서는 활동성보다 야성의 기호로 쓰인다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003755/index.html"},{"id":"MEJE-KW-003756","row_version":1,"title":"땋은 머리로 야성적 전사 표현하기","original":"Braids of Barbarism","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"전사의 긴 머리를 땋아 문명 밖의 거친 인물처럼 보이게 한다. 헤어스타일과 문화의 가치를 단순히 연결하는 관습을 돌아볼 필요가 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003756/index.html"},{"id":"MEJE-KW-003757","row_version":1,"title":"본 장면을 기억에서 지우고 싶다고 말하기","original":"Brain Bleach","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 충격적이거나 민망한 장면을 본 뒤 기억을 씻고 싶다고 과장한다. 실제 기억 변화가 아니라 강한 거부감의 말이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003757/index.html"},{"id":"MEJE-KW-003758","row_version":2,"title":"뇌와 기계를 직접 연결하는 장치","original":"Brain–Computer Interface","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"세계 안의 기술이 인물의 신경 활동과 기계의 작동을 이어 준다. 생각이 어느 방향으로 오가는지에 따라 사용과 감시의 경계가 달라진다. 뇌의 신호를 기계에 잇는 과정이 더 커지면 정신을 디지털 기록으로 옮기기의 가능성까지 묻게 된다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003758/index.html"},{"id":"MEJE-KW-003759","row_version":1,"title":"높은 지능이 초능력으로 이어진다는 설정","original":"Brain Critical Mass","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"작품이 뛰어난 사고 능력을 마음의 힘이나 기계 조작 능력의 근거로 삼는다. 실제 뇌의 법칙이 아니라 그 세계가 만든 능력의 기원이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003759/index.html"},{"id":"MEJE-KW-003760","row_version":1,"title":"유능한 사람이 조직을 떠나기","original":"Brain Drain","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"능력 있는 구성원들이 더 나은 조건이나 안전을 찾아 한 조직을 떠난다. 남은 사람의 부담과 조직이 바꾸어야 할 조건이 드러난다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003760/index.html"},{"id":"MEJE-KW-003761","row_version":1,"title":"정신적 충격이 곧 뇌의 열병이 되는 허구","original":"Brain Fever","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"작품이 놀람이나 스트레스 뒤에 갑자기 심한 열병이 생겼다고 설명한다. 실제 진단과 구분되는 서사적 몸의 규칙이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003761/index.html"},{"id":"MEJE-KW-003762","row_version":2,"title":"뇌를 먹으려는 괴물","original":"Brain Food","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"괴물이 사람의 뇌를 특별한 먹이로 여기며 쫓는다. 먹이의 선택이 지능이나 기억을 빼앗는 위협의 이미지가 된다. 뇌를 먹는 존재와 뇌의 형태를 한 괴물는 뇌를 괴물의 이미지로 쓰는 방식이 다르다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-003762/index.html"},{"id":"MEJE-KW-003763","row_version":1,"title":"찬 음식을 먹고 머리를 움켜쥐기","original":"Brain Freeze","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"아주 차가운 음식을 급히 먹은 인물이 갑작스런 불편함에 크게 반응한다. 짧은 몸의 감각을 과장해 웃음을 만드는 장면이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003763/index.html"},{"id":"MEJE-KW-003764","row_version":2,"title":"몸과 분리돼 용기에 담긴 뇌","original":"Brain in a Jar","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"뇌만 남겨 생명을 이어 가는 존재가 용기 속에서 생각하고 대화한다. 몸이 바뀌어도 인격이 이어지는지 묻는 설정이다. 몸에서 분리된 뇌를 다른 몸으로 옮기면 뇌를 다른 몸에 옮기는 허구 기술의 설정이 된다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-003764/index.html"},{"id":"MEJE-KW-003765","row_version":1,"title":"아름다움과 낮은 지능을 묶는 인물 틀","original":"Brainless Beauty","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"매력적인 외모를 가진 인물을 판단력이 부족한 사람처럼 반복해서 그린다. 외모와 지능 사이에 근거 없는 연결을 만드는 고정관념이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003765/index.html"},{"id":"MEJE-KW-003766","row_version":1,"title":"뇌의 형태를 한 괴물","original":"Brain Monster","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"뇌가 밖으로 드러나거나 뇌 자체가 움직이는 존재가 나타난다. 생각의 기관을 몸처럼 보여 주며 낯선 지능의 위협을 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-003766/index.html"},{"id":"MEJE-KW-003767","row_version":1,"title":"지적 능력과 성적 취향을 묶는 관습","original":"Brains and Bondage","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 특정한 성적 취향을 가진 인물을 특별히 지적인 사람으로 그린다. 취향과 지능을 자동으로 연결하는 인물 공식인지 비판적으로 본다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003767/index.html"},{"id":"MEJE-KW-003768","row_version":2,"title":"생각하는 사람과 힘쓰는 사람의 한 쌍","original":"Brains and Brawn","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 사람은 계획하고 다른 사람은 물리적 실행을 맡는 두 인물이 협력한다. 서로의 역할이 고정되지 않을 때 관계가 더 입체적이다. 역할을 나눠 협력하는 관계는 지능과 육체적 힘을 대립시키기처럼 두 능력을 맞서는 것으로만 볼 필요가 없음을 보여 준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003768/index.html"},{"id":"MEJE-KW-003769","row_version":2,"title":"똑똑한 악역과 힘센 영웅의 대비","original":"Brains Evil, Brawn Good","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 계획은 악역의 재주, 육체적 힘은 영웅의 덕처럼 배치한다. 지성과 힘을 선악으로 나누는 관습을 돌아볼 수 있다. 지능과 육체적 힘을 대립시키기의 구도에 선악의 표지까지 덧씌운 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003769/index.html"},{"id":"MEJE-KW-003770","row_version":1,"title":"생각하느라 머리에서 연기 나기","original":"Brain Smoke","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 어려운 문제를 붙들자 머리 위로 연기가 오른다. 생각의 부담을 기계의 과열처럼 바꾸어 보여 주는 농담이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003770/index.html"},{"id":"MEJE-KW-003771","row_version":1,"title":"지능과 육체적 힘을 대립시키기","original":"Brains Versus Brawn","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"이야기가 똑똑한 사람과 힘센 사람을 서로 반대되는 유형처럼 세운다. 한 인물 안에 두 능력이 함께 있을 가능성을 가리는 구도다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-003771/index.html"},{"id":"MEJE-KW-003772","row_version":2,"title":"뇌를 훔쳐 가는 사건","original":"Brain Theft","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물의 뇌가 사라져 누가 가져갔고 왜 필요한지 추적한다. 장기의 상실을 정체성과 통제권의 위기로 바꾸는 허구 사건이다. 빼앗긴 뇌를 다른 몸에 넣으려 한다면 뇌를 다른 몸에 옮기는 허구 기술가 사건의 목적이 될 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003772/index.html"},{"id":"MEJE-KW-003773","row_version":2,"title":"뇌를 다른 몸에 옮기는 허구 기술","original":"Brain Transplant","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"작품 속 기술이 한 몸의 뇌를 다른 몸에서 깨어나게 한다. 기억과 인격, 새 몸의 권리를 어떻게 다루는지가 설정의 중심이다. 뇌를 몸째 옮기는 방식과 정신을 디지털 기록으로 옮기기처럼 기록으로 옮기는 방식을 구분한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003773/index.html"},{"id":"MEJE-KW-003774","row_version":2,"title":"정신을 디지털 기록으로 옮기기","original":"Brain Uploading","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인물의 생각과 기억을 데이터로 남겨 다른 매체에서 이어 가려 한다. 복제된 존재가 같은 사람인지가 세계의 논쟁이 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003774/index.html"},{"id":"MEJE-KW-003775","row_version":3,"title":"타인의 의지에 따라 행동하도록 세뇌되기","original":"Brainwashed","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 외부의 조작으로 자신의 선택과 어긋나는 행동을 한다. 조작된 시간과 벗어난 뒤의 기억이 관계를 바꾼다. 조작된 행동이 가장 가까운 사람에게 향하면 세뇌당해 친구를 공격하기의 갈등이 된다. 상대의 의지를 바꾸는 일이 더 큰 선을 위해 마음을 고친다는 주장라는 명분으로 정당화되기도 한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003775/index.html"},{"id":"MEJE-KW-003776","row_version":2,"title":"세뇌당해 친구를 공격하기","original":"Brainwashed and Crazy","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"조작된 인물이 친구를 적으로 여기거나 명령에 따라 해친다. 공격을 멈추는 일과 조작된 사람의 책임을 어떻게 볼지가 갈등이다. 친구를 공격한 뒤 조작에서 벗어나도 세뇌가 풀린 뒤에도 남는 흔적가 관계에 남을 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003776/index.html"},{"id":"MEJE-KW-003777","row_version":2,"title":"의식을 조작해 결혼식에 세우기","original":"Brainwashed Bride","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 자기 뜻과 달리 혼인에 동의하도록 정신을 조작당한다. 결혼의 형식이 갖춰져도 당사자의 동의가 없다는 점이 사건의 핵심이다. 혼인에 대한 동의를 빼앗는 데 타인의 의지에 따라 행동하도록 세뇌되기의 힘을 쓴 사건이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003777/index.html"},{"id":"MEJE-KW-003778","row_version":2,"title":"더 큰 선을 위해 마음을 고친다는 주장","original":"Brainwashing for the Greater Good","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"좋은 결과를 내세워 다른 사람의 생각을 강제로 바꾸려 한다. 피해를 막을 책임과 개인의 자유를 침해하는 권력이 충돌한다. 좋은 결과를 주장해도 타인의 의지에 따라 행동하도록 세뇌되기의 강제성과 피해는 남는다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-003778/index.html"},{"id":"MEJE-KW-003779","row_version":2,"title":"세뇌가 풀린 뒤에도 남는 흔적","original":"Brainwash Residue","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"외부 조작에서 벗어난 인물에게 습관이나 감정의 일부가 남는다. 자유를 되찾은 뒤에도 이전의 경험을 관계 속에서 다뤄야 한다. 타인의 의지에 따라 행동하도록 세뇌되기에서 벗어났다는 사실과 그 경험의 흔적이 사라졌다는 말은 다르다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003779/index.html"},{"id":"MEJE-KW-003780","row_version":1,"title":"머릿속에 있는 조종석","original":"Brain with a Manual Control","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"작품이 뇌 안을 작은 조종실처럼 꾸며 누군가가 몸의 움직임을 제어하게 한다. 생각과 행동을 버튼으로 나누는 만화적 몸의 규칙이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003780/index.html"},{"id":"MEJE-KW-003781","row_version":1,"title":"아기인데도 뛰어난 지능을 지닌 인물","original":"Brainy Baby","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"아주 어린 인물이 어른도 어려워하는 문제를 풀고 계획을 세운다. 말과 행동의 나이 차이가 웃음이나 불안을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003781/index.html"},{"id":"MEJE-KW-003782","row_version":1,"title":"갈색 머리를 지능의 표지로 쓰기","original":"Brainy Brunette","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"여러 머리색의 인물을 나란히 놓고 갈색 머리 인물에게 지적 역할을 맡긴다. 머리색과 능력을 묶는 고정관념을 드러내는 표현이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003782/index.html"},{"id":"MEJE-KW-003783","row_version":1,"title":"똑똑한 돼지라는 동물 틀","original":"Brainy Pig","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 돼지를 다른 동물보다 영리한 인물로 그려 계획과 말재주를 맡긴다. 실제 동물에 대한 단정 대신 창작 속 성격 부여로 읽는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003783/index.html"},{"id":"MEJE-KW-003784","row_version":1,"title":"분노해 차를 급히 멈추기","original":"Brake Angrily","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"운전자가 들은 말에 화가 나 갑자기 차를 세운다. 반응의 크기가 대화의 긴장과 동승자의 불안을 함께 높인다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003784/index.html"},{"id":"MEJE-KW-003785","row_version":1,"title":"갈라진 길이 다시 합쳐지는 이야기","original":"Branch-and-Bottleneck Plot Structure","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"선택에 따라 사건의 중간 경로가 달라지지만 뒤에는 공통 장면으로 돌아온다. 선택의 자유와 다시 만나는 줄기의 범위를 함께 설계한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003785/index.html"},{"id":"MEJE-KW-003786","row_version":1,"title":"변신한 모습이 별도 존재로 갈라지기","original":"Branched-Off Transformation","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"한 사람의 변신 형태가 원래 인물과 분리돼 스스로 행동한다. 둘의 기억과 권리, 원본을 대신할 가능성이 새 갈등이 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003786/index.html"},{"id":"MEJE-KW-003787","row_version":2,"title":"없는 무기를 있는 척하며 위협하기","original":"Brandishment Bluff","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 실제로 갖고 있지 않은 무기가 있다고 믿게 만들어 상대의 행동을 멈추려 한다. 속임수가 통하는 시간은 상대가 무엇을 확인할 수 있는지에 달려 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003787/index.html"},{"id":"MEJE-KW-003788","row_version":2,"title":"유명 상표가 더 좋다는 믿음","original":"Brand Names Are Better","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"인물이 품질을 살피기 전에 잘 알려진 상표라는 이유만으로 물건을 높게 평가한다. 실제 쓰임과 이름이 주는 기대 사이의 차이가 선택을 드러낸다. 상표에 대한 신뢰가 널리 퍼지면 이름 자체가 보통말이 되는 상표명이 물건의 보통 이름이 되기로 이어질 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003788/index.html"},{"id":"MEJE-KW-003789","row_version":2,"title":"상표명이 물건의 보통 이름이 되기","original":"Brand Name Takeover","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"특정 회사의 이름으로 비슷한 종류의 모든 물건을 부른다. 일상 언어에 스민 상표가 대화의 오해나 농담을 만든다. 실제 이름을 피하면서 익숙한 상품을 떠올리게 하는 실존 상표를 닮은 가짜 상품와 다른 방식의 상표 표현이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003789/index.html"},{"id":"MEJE-KW-003790","row_version":1,"title":"실존 상표를 닮은 가짜 상품","original":"Brand X","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 실제 상품의 색과 모양을 떠올리게 하면서 다른 이름의 물건을 등장시킨다. 익숙한 소비 생활을 보여 주면서도 허구의 세계에 맞춘다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003790/index.html"},{"id":"MEJE-KW-003791","row_version":1,"title":"대담함을 신체 비유로 칭찬하기","original":"Brass Balls","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"위험을 감수한 인물의 배짱을 성별화된 신체 비유로 과장해 말한다. 말의 거친 인상과 실제 행동의 용기를 따로 살핀다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003791/index.html"},{"id":"MEJE-KW-003792","row_version":1,"title":"새총을 들고 다니는 장난꾸러기","original":"Brats with Slingshots","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"어린 인물이 새총을 손에 들거나 주머니에 넣고 다니며 짓궂은 행동을 한다. 작은 도구가 놀이와 위협의 경계에 놓인다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003792/index.html"},{"id":"MEJE-KW-003793","row_version":2,"title":"음식에 까다로운 요구를 쏟아내기","original":"Bratty Food Demand","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 음식을 차려 준 사람에게 사소한 모양과 순서를 계속 요구한다. 취향 자체보다 타인의 수고를 대하는 태도가 갈등을 만든다. 어린 인물의 요구가 몸집은 작지만 거침없는 아이의 태도를 보여 주는 장면이 된다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003793/index.html"},{"id":"MEJE-KW-003794","row_version":2,"title":"몸집은 작지만 거침없는 아이","original":"Bratty Half-Pint","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"어린 인물이 나이를 이유로 얕보지 말라며 큰소리치고 먼저 행동한다. 기세와 아직 부족한 판단이 함께 캐릭터를 이룬다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003794/index.html"},{"id":"MEJE-KW-003795","row_version":1,"title":"사춘기 딸을 문제아로만 그리기","original":"Bratty Teenage Daughter","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"가족 이야기에서 십대 딸의 행동을 허영과 불평으로만 설명한다. 그가 원하는 것과 가족이 듣지 않는 말도 함께 살필 필요가 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003795/index.html"},{"id":"MEJE-KW-003796","row_version":1,"title":"두려움을 밀어내는 노래","original":"Bravado Song","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 위험 앞에서 겁내지 않겠다는 마음을 노래한다. 밝은 가사와 흔들리는 행동의 차이가 진짜 용기를 드러낼 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003796/index.html"},{"id":"MEJE-KW-003797","row_version":1,"title":"스코틀랜드인을 용감한 전사로 그리기","original":"Brave Scot","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"스코틀랜드 출신 인물에게 억센 말투와 전투의 용기를 한꺼번에 부여한다. 출신 지역을 개별 인물의 성격으로 단정하는 관습을 구분한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003797/index.html"}]}.cards;